{
  "routing": {
    "config": {
      "routerClass": "sap.f.routing.Router",
      "type": "View",
      "viewType": "XML",
      "path": "my.app.view",
      "controlId": "fcl"
    },
    "routes": [
      { "name": "list", "pattern": ":layout:", "target": ["list"] },
      { "name": "detail", "pattern": "detail/{productId}/{layout}", "target": ["list", "detail"] }
    ],
    "targets": {
      "list": { "name": "List", "controlAggregation": "beginColumnPages" },
      "detail": { "name": "Detail", "controlAggregation": "midColumnPages" }
    }
  }
}

import FlexibleColumnLayoutSemanticHelper from "sap/f/FlexibleColumnLayoutSemanticHelper";
import LayoutType from "sap/f/LayoutType";
import FlexibleColumnLayout from "sap/f/FlexibleColumnLayout";

const helper = FlexibleColumnLayoutSemanticHelper.getInstanceFor(
  this.byId("fcl") as FlexibleColumnLayout,
  { defaultTwoColumnLayoutType: LayoutType.TwoColumnsMidExpanded }
);

// level 1 = list + detail
const nextUIState = helper.getNextUIState(1);
(this.getModel("fcl") as JSONModel).setProperty("/layout", nextUIState.layout);
// nextUIState also tells which buttons to show (full screen, exit full screen, close)

sap.ui.require(["sap/ui/Device"], function (Device) {
  Device.media.attachHandler(function (params) {
    // params.name is "Phone" | "Tablet" | "Desktop"
    this.getModel("view").setProperty("/screen", params.name);
  }, this, Device.media.RANGESETS.SAP_STANDARD);
}.bind(this));
